  _schema = XCHierarchicalElement._schema.copy()
  _schema.update({
    ""children"": [1, XCHierarchicalElement, 1, 1, []],
    ""name"":     [0, str,                   0, 0],
    ""path"":     [0, str,                   0, 0],
  })

  def GetChildByName(self, name):
    # TODO(mark): This should raise an error if more than one child is present
    # with the same name.
    if not ""children"" in self._properties:
      return None

    for child in self._properties[""children""]:
      if child.Name() == name:
        return child

    return None

  def GetChildByPath(self, path):
    # TODO(mark): This should raise an error if more than one child is present
    # with the same path.  Also, it should probably resolve paths and handle
    # different sourceTree values.
    if not ""children"" in self._properties:
      return None

    for child in self._properties[""children""]:
      if ""path"" in child._properties and child._properties[""path""] == path:
        return child

    return None

  def GetChildByRemoteObject(self, remote_object):
    # This method is a little bit esoteric.  Given a remote_object, which
    # should be a PBXFileReference in another project file, this method will
    # return this group's PBXReferenceProxy object serving as a local proxy
    # for the remote PBXFileReference.
    if not ""children"" in self._properties:
      return None

    for child in self._properties[""children""]:
      if not isinstance(child, PBXReferenceProxy):
        continue

      container_proxy = child._properties[""remoteRef""]
      if container_proxy._properties[""remoteGlobalIDString""] == remote_object:
        return child

    return None"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}, {""method_name"": ""PBXProject.Path"", ""path"": ""xcodeproj_file.py"", ""class_name"": ""PBXProject"", ""start_line"": 1362, ""end_line"": 1363, ""source"": ""def Path(self):
