            color = self.setting_service.get(""private_message_color"").get_font_color() if add_color else """"
            pages = self.get_text_pages(msg, self.setting_service.get(""private_message_max_page_length"").get_value())
            for page in pages:
                self.logger.log_tell(conn.id, ""To"", self.character_service.get_char_name(char_id), page)
                packet = client_packets.PrivateMessage(char_id, color + page, ""\0"")
                conn.add_packet_to_queue(packet)

            if fire_outgoing_event:
                self.event_service.fire_event(self.OUTGOING_PRIVATE_MESSAGE_EVENT, DictObject({""char_id"": char_id,
                                                                                               ""message"": msg}))"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}, {""method_name"": ""OnlineController.get_online_output"", ""path"": ""modules/standard/online/online_controller.py"", ""class_name"": ""OnlineController"", ""start_line"": 178, ""end_line"": 207, ""source"": ""def get_online_output(self):
        blob = """"
        count = 0
        for channel, _ in self.channels:
            online_list = self.get_online_characters(channel)
            if len(online_list) == 0:
                continue

            blob += ""<header2>%s Channel</header2>\n"" % channel

            current_main = """"
            for row in online_list:
                if current_main != row.main:
                    count += 1
                    blob += ""\n%s\n"" % self.text.make_tellcmd(row.main, ""alts %s"" % row.main)
                    current_main = row.main

                afk = """"
                if row.afk_dt > 0:
                    afk = "" - <highlight>%s (%s ago)</highlight>"" % (row.afk_reason, self.util.time_to_readable(int(time.time()) - row.afk_dt))

                org_info = """"
                if channel == self.PRIVATE_CHANNEL:
                    if row.org_name:
                        org_info = "", %s of %s"" % (row.org_rank_name, row.org_name)

                blob += "" | %s (%d/<green>%d</green>) %s %s%s%s\n"" % (row.name, row.level or 0, row.ai_level or 0, row.faction, row.profession, afk, org_info)
            blob += ""\n\n""

        return ChatBlob(""Online (%d)"" % count, blob)"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",,[],[],True,skipped_fixer_only,"def private_channel_send_logon_event(self, event_type, event_data):

